std::map<uintptr_t,QPointer<ScrollPanel>> panels;
uintptr_t create(uintptr_t owner,UiScrollCallback callback,UiScrollState const* state){if(!qApp||!state)return 0;auto panel=new ScrollPanel(owner,callback,*state,!owner);auto id=uintptr_t(panel->winId());panels[id]=panel;return id;}
void update(uintptr_t id,UiScrollState const* state){auto it=panels.find(id);if(it!=panels.end()&&it->second&&state)it->second->refresh(*state);}
void show(uintptr_t id,int visible){auto it=panels.find(id);if(it==panels.end()||!it->second)return;auto panel=it->second;if(panel->isVisible()!=bool(visible))panel->setVisible(visible);if(visible&&!panel->testAttribute(Qt::WA_DontShowOnScreen)&&!IsWindowVisible(HWND(panel->winId())))SetWindowPos(HWND(panel->winId()),HWND_TOPMOST,0,0,0,0,SWP_NOMOVE|SWP_NOSIZE|SWP_NOACTIVATE|SWP_SHOWWINDOW);}
void destroy(uintptr_t id){auto it=panels.find(id);if(it==panels.end())return;auto panel=it->second;panels.erase(it);if(panel)panel->retire();}
